class Stack<T> {
    private val items = mutableListOf<T>()

    fun push(item: T) {
        items.add(item)
    }

    fun pop(): T {
        if (items.isEmpty()) {
            throw IllegalStateException("Stack is empty")
        }
        return items.removeAt(items.size - 1)
    }

    fun isEmpty(): Boolean {
        return items.isEmpty()
    }
}

