import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testPushAndPop() {
        val stack = Stack<Int>()
        stack.push(10)
        stack.push(20)
        stack.push(30)
        Assert.assertEquals(30, stack.pop())
        Assert.assertEquals(20, stack.pop())
        Assert.assertEquals(10, stack.pop())
    }

    @Test
    fun testIsEmpty() {
        val stack = Stack<String>()
        Assert.assertTrue(stack.isEmpty())
        stack.push("Tribots")
        Assert.assertFalse(stack.isEmpty())
        stack.pop()
        Assert.assertTrue(stack.isEmpty())
    }

    @Test
    fun testStringStack() {
        val stack = Stack<String>()
        stack.push("Red")
        stack.push("Blue")
        Assert.assertEquals("Blue", stack.pop())
        Assert.assertEquals("Red", stack.pop())
    }

    @Test
    fun testPopEmptyStackMessage() {
        val stack = Stack<Int>()
        try {
            stack.pop()
            Assert.fail("Should have thrown IllegalStateException")
        } catch (e: IllegalStateException) {
            Assert.assertEquals("Stack is empty", e.message)
        }
    }
}
